        '<!DOCTYPE html>',
        '<html><head></head><body>',
        '<div id="main">' + optionalMarkup + '</div>',
        bundle(req, 'vendor', variations),
        bundle(req, 'main', variations),
        '</body></html>',
    ].join('\n');

    res.send(html);
    res.end();
});

