39	        this.processStart = Date.now();
40	
41	        this.nameMaxLen = options.nameMaxLen || 30;
42	    }
43	
44	    groupData(data, columnIndex) {
45	        const grouping = {};
46	
47	        data.forEach((point) => {
48	            const columnName = point.name.split(':')[columnIndex];
49	            grouping[columnName] = grouping[columnName] || [];
50	
51	            grouping[columnName].push(point);
52	        });
53	
54	        return grouping;
55	    }
56	
57	    _print(data, dimensions, indentation = 0) {
58	        const [dimension] = dimensions;
59	        const subData = this.groupData(data, dimension);
60	
61	        if (dimensions.length > 1) {
62	            return Object.keys(subData).forEach((groupedName) => {
63	                const dataPart = subData[groupedName];
64	
65	                console.log(
66	                    new Array(indentation + 1).join('  ') +
67	                        style('underline', groupedName)
68	                );
69	                this._print(dataPart, dimensions.slice(1), indentation + 1);
70	            });
71	        }
72	
73	        // Group/aggregate the data
74	        const points = Object.keys(subData)
75	            .map((groupedName) => {
76	                const dataPart = subData[groupedName];
77	
78	                // Special case: make the labels pretty!
79	                if (
80	                    indentation === 0 &&
81	                    dimensions.length === 1 &&
82	                    dimension !== 1
83	                ) {
84	                    // Example: <pid> (groupNameA+groupNameB+groupNameC+etc…)
85	                    const set = new Set();
86	                    dataPart.forEach((p) => set.add(p.name.split(':')[1]));
87	                    const groupNames =
88	                        Array.from(set.keys()).sort().slice(0, 3).join('+') +
89	                        (set.size > 3 ? '+etc…' : '');
90	                    groupedName += ` (${groupNames})`;
91	                }
92	                const aggregate = dataPart.reduce(
93	                    (reduced, point) => reduced + point.after - point.before,
94	                    0
95	                );
96	                return { name: groupedName, aggregate };
97	            })
98	            .sort((a, b) => b.aggregate - a.aggregate);
99	
100	        // Sum all time in this particular group for percentage
101	        const totalAggregateTime = points.reduce(
102	            (reduced, { aggregate }) => reduced + aggregate,
103	            0
104	        );
105	
106	        // Textify
107	        const tabledText = points
108	            .map(({ name, aggregate }) => {
109	                const percent = totalAggregateTime
110	                    ? (aggregate / totalAggregateTime) * 100
111	                    : 0;
112	                // 7 for the time string, 4 for percent string, 3 to compensate for column char of the table
113	                const maxBarSize =
114	                    (process.stdout.columns || 80) -
115	                    this.nameMaxLen -
116	                    7 -
117	                    4 -
118	                    6;
119	                return [
120	                    // maximum of 20
121	                    padRight(
122	                        new Array(indentation + 1).join('  ') +
123	                            name.slice(0, this.nameMaxLen),
124	                        this.nameMaxLen
125	                    ),
126	                    // max of 7 characters
127	                    padLeft(prettyMs(aggregate).slice(0, 7), 7),
128	                    getBarText(percent, maxBarSize),
129	                    // maximum of 4 character (number + '%')
130	                    padLeft(`${Math.round(percent)}%`, 4),
131	                ].join('  ');
132	            })
133	            .join('\n');
134	
135	        // Print the table!
136	        console.log(tabledText);
137	    }
